corrected_code:
package controllers

import (
	"net/http"
	"github.com/golang-jwt/jwt/v5"
	"github.com/labstack/echo/v4"
	"myapp/payments"
)

type CardController struct {
	Gateway payments.PaymentGateway
}

func (ctrl *CardController) DeleteStoredCard(c echo.Context) error {
	cardID := c.Param("cardID")
	userToken := c.Get("user").(*jwt.Token)
	claims := userToken.Claims.(jwt.MapClaims)
	authUserID := claims["sub"].(string)

	err := ctrl.Gateway.DeletePaymentCardForUser(c.Request().Context(), cardID, authUserID)
	if err != nil {
		return c.JSON(http.StatusForbidden, echo.Map{"error": "Card not found or access denied"})
	}

	return c.NoContent(http.StatusNoContent)
}
